#!/usr/bin/env bash
set -euo pipefail
test "$(id -u)" = 0 || { echo 'Please run as root.'; exit 1; }
PAYLOAD=$(mktemp /tmp/shop-ledger.XXXXXX.tar.gz)
trap 'rm -f "$PAYLOAD"' EXIT
base64 -d > "$PAYLOAD" <<'LEDGER_PAYLOAD'

LEDGER_PAYLOAD
APP=/var/www/shop-ledger
CONF=/etc/nginx/conf.d/shop-ledger-8080.conf
if ss -lntH | awk '{print $4}' | grep -qE ':8080$' && [ ! -f "$CONF" ]; then
  echo 'Port 8080 is already used. No changes made. Return to the chat for help.'; exit 1
fi
if ! command -v nginx >/dev/null; then
  apt-get update
  DEBIAN_FRONTEND=noninteractive apt-get install -y nginx
fi
nginx -t
STAMP=$(date +%Y%m%d%H%M%S)
RELEASE="$APP/releases/$STAMP"
mkdir -p "$RELEASE"
tar -xzf "$PAYLOAD" -C "$RELEASE"
test -f "$RELEASE/index.html"
chmod -R a+rX "$RELEASE"
OLD=$(readlink "$APP/current" || true)
if [ -f "$CONF" ]; then cp "$CONF" "$CONF.backup-$STAMP"; fi
cat > "$CONF" <<'NGINX'
server {
  listen 8080;
  server_name _;
  root /var/www/shop-ledger/current;
  index index.html;
  charset utf-8;
  add_header X-Content-Type-Options nosniff always;
  location / { try_files $uri $uri/ =404; }
  location ~ /\. { deny all; }
}
NGINX
if ! nginx -t; then
  if [ -f "$CONF.backup-$STAMP" ]; then cp "$CONF.backup-$STAMP" "$CONF"; else mv "$CONF" "$CONF.failed-$STAMP"; fi
  echo 'Nginx validation failed. Previous configuration preserved.'; exit 1
fi
ln -sfn "$RELEASE" "$APP/current"
if ! systemctl enable --now nginx || ! systemctl reload nginx; then
  if [ -n "$OLD" ]; then ln -sfn "$OLD" "$APP/current"; fi
  echo 'Service did not start. Return to the chat with this output.'; exit 1
fi
if command -v ufw >/dev/null && ufw status | grep -q 'Status: active'; then ufw allow 8080/tcp; fi
if command -v curl >/dev/null; then curl -fsS http://127.0.0.1:8080/ -o /dev/null; fi
echo 'DEPLOYMENT COMPLETE: http://121.40.217.40:8080'
echo 'Allow inbound TCP 8080 in the Alibaba Cloud firewall/security group.'